from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    distinct_strings = []  # Initialize an empty list to store the distinct strings
    current_string = ""  # Initialize an empty string to track the current collection

    for char in paren_string:
        if char == '(':
            if current_string:
                distinct_strings.append(current_string)
            current_string = "("
        elif char == ')':
            current_string += ")"
            distinct_strings.append(current_string)
            current_string = ""

    if current_string:  # In case the last collection is not closed with a closing parenthesis
        distinct_strings.append(current_string)

    return distinct_strings
